using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1️⃣  Strongly-typed metadata: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// 2️⃣  Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//     Use a resolver that only knows about Person (not about UnknownRecord).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out var found))
    Console.WriteLine($"\n✔ Metadata for Person IS available (kind: {found!.Kind})");
else
    Console.WriteLine("\n✘ Metadata for Person is NOT available");

if (limited.TryGetTypeInfo(typeof(UnknownRecord), out _))
    Console.WriteLine("✔ Metadata for UnknownRecord IS available");
else
    Console.WriteLine("✘ Metadata for UnknownRecord is NOT available (no exception thrown)");

// --- Types ---
record Person(string Name, int Age);
record UnknownRecord(string Data);

// A custom resolver that only resolves Person
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signal "not available"
    }
}

